/*
 * prog36_pascal_triangle
 *
 * Behaviour (as observed in the original binary):
 *
 *   - No command‑line argument          → prints "NO_INPUT"
 *   - Argument cannot be parsed as an integer → prints "BAD_INPUT"
 *   - Parsed number < 0                → prints "BAD_INPUT"
 *   - Parsed number == 0               → prints "EMPTY"
 *   - Parsed number  > 60               → prints "OUT_OF_RANGE"
 *   - Otherwise prints Pascal's triangle with the given number of rows.
 *
 * Each row is printed on its own line, numbers are separated by a single
 * space, and no trailing space appears at the end of a line.
 */

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long long n = strtol(argv[1], &endptr, 10);

    /* strtol failed to convert any characters */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* negative numbers are considered bad input */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    /* the original program allocated an array of 61 elements (0 … 60) */
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- Pascal's triangle ---------- */
    long long row[61] = {0};
    row[0] = 1;                     /* first row */

    for (long long i = 0; i < n; ++i) {
        /* print the current row */
        for (long long j = 0; j <= i; ++j) {
            if (j) putchar(' ');
            printf("%lld", row[j]);
        }
        putchar('\n');

        /* generate the next row (unless this was the last one) */
        if (i + 1 < n) {
            row[i + 1] = 1;                     /* right‑most 1 */
            for (long long k = i; k > 0; --k) { /* Pascal's rule */
                row[k] = row[k] + row[k - 1];
            }
        }
    }

    return 0;
}
